@transaction.atomic
def seed_phase3a():
    print("GrowthSpare Phase 3A content-authority seeding started...")

    author = User.objects.filter(username="furqankafil").first() or User.objects.filter(is_staff=True).first()
    if author is None:
        raise RuntimeError(
            "No author account found. Run seed_database.py first (or create a staff "
            "user) so blog articles can be linked to an author."
        )
    print(f"-> Using author: {author.username}")

    category_cache = {}
    for category_slug, category_name in (
        ("website-development", "Website Development"),
        ("seo-optimization", "SEO Optimization"),
        ("ai-automation", "AI Automation"),
        ("crm-saas-solutions", "CRM & SaaS Solutions"),
    ):
        cat, _ = BlogCategory.objects.update_or_create(
            slug=category_slug, defaults={"name": category_name}
        )
        category_cache[category_slug] = cat

    created, updated = 0, 0
    for article in ARTICLES:
        data = dict(article)
        title = data.pop("title")
        category = category_cache[data.pop("category_slug")]
        post, was_created = BlogPost.objects.update_or_create(
            title=title,
            defaults={**data, "category": category, "author": author, "is_published": True},
        )
        if was_created:
            created += 1
        else:
            updated += 1

    print(f"-> {created} articles created, {updated} existing articles updated.")
    print("GrowthSpare Phase 3A seeding completed successfully.")


if __name__ == "__main__":
    seed_phase3a()
